#!/usr/bin/env python3
"""headlite.py - a streaming implementation of head(1).

Supports:
  -n NUM     print the first NUM lines
  -n -K      print all but the last K lines (GNU extension)
  -c NUM     print the first NUM bytes
  -c -K      print all but the last K bytes (GNU extension)

With no option, defaults to the first 10 lines (GNU behaviour).

The negative (-K) forms are truly streaming: they hold at most K lines /
K bytes in memory at any time, never the whole input. All I/O happens on
raw byte streams (sys.stdin.buffer / sys.stdout.buffer), so -c is
byte-exact and no unicode decoding is ever attempted.
"""

import argparse
import sys
from collections import deque

CHUNK = 1 << 16  # 64 KiB read size


def parse_count(text: str) -> int:
    """Parse '12' or '-12' into a signed int."""
    try:
        return int(text, 10)
    except ValueError:
        raise SystemExit(f"headlite: invalid count: {text!r}")


def head_lines_positive(src, dst, n: int) -> None:
    """Print the first n lines."""
    if n <= 0:
        return
    for i, line in enumerate(src):
        if i >= n:
            break
        dst.write(line)


def head_lines_negative(src, dst, k: int) -> None:
    """Print all but the last k lines using only a k-line buffer."""
    if k <= 0:
        # All but the last 0 lines == everything; still fully streamed.
        for line in src:
            dst.write(line)
        return
    buf = deque(maxlen=k)
    append = buf.append
    pop = buf.popleft
    for line in src:
        if len(buf) == k:
            # Buffer full: this line is guaranteed NOT to be among the
            # last k lines, so flush it now and keep streaming.
            dst.write(pop())
        append(line)
    # Anything left in buf is part of the final k lines: discarded.


def head_bytes_positive(src, dst, n: int) -> None:
    """Print the first n bytes."""
    remaining = max(n, 0)
    while remaining > 0:
        chunk = src.read(min(CHUNK, remaining))
        if not chunk:
            break
        dst.write(chunk)
        remaining -= len(chunk)


def head_bytes_negative(src, dst, k: int) -> None:
    """Print all but the last k bytes using only a k-byte buffer."""
    if k <= 0:
        while True:
            chunk = src.read(CHUNK)
            if not chunk:
                break
            dst.write(chunk)
        return
    buf = deque()
    size = 0
    while True:
        chunk = src.read(CHUNK)
        if not chunk:
            break
        buf.append(chunk)
        size += len(chunk)
        # Evict from the front until only the most recent k bytes remain;
        # evicted bytes are known to be safely inside the output region.
        while size > k:
            first = buf[0]
            excess = size - k
            if len(first) <= excess:
                dst.write(first)
                size -= len(first)
                buf.popleft()
            else:
                dst.write(first[:excess])
                buf[0] = first[excess:]
                size -= excess
                break
    # Remaining buffer holds the final k bytes: discarded.


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(
        prog="headlite",
        description="Stream the first part of a file (or all but its tail).",
    )
    group = parser.add_mutually_exclusive_group()
    group.add_argument(
        "-n", "--lines", metavar="NUM", default=None,
        help="first NUM lines; negative means all but the last |NUM| lines",
    )
    group.add_argument(
        "-c", "--bytes", dest="bytes_count", metavar="NUM", default=None,
        help="first NUM bytes; negative means all but the last |NUM| bytes",
    )
    parser.add_argument(
        "file", nargs="?", default="-",
        help="input file (default: stdin)",
    )
    args = parser.parse_args(argv)

    if args.file == "-":
        src = sys.stdin.buffer
        close_src = False
    else:
        src = open(args.file, "rb")
        close_src = True

    try:
        dst = sys.stdout.buffer
        if args.lines is not None:
            n = parse_count(args.lines)
            if n >= 0:
                head_lines_positive(src, dst, n)
            else:
                head_lines_negative(src, dst, -n)
        elif args.bytes_count is not None:
            n = parse_count(args.bytes_count)
            if n >= 0:
                head_bytes_positive(src, dst, n)
            else:
                head_bytes_negative(src, dst, -n)
        else:
            head_lines_positive(src, dst, 10)  # GNU default: 10 lines

        dst.flush()
    finally:
        if close_src:
            src.close()
    return 0


if __name__ == "__main__":
    sys.exit(main())

