def parse_count(text: str) -> tuple[bool, int]:
    """Parse '12' or '-12' into (is_negative, magnitude).

    Sign is taken from the raw text so that '-0' keeps its meaning
    ('all but the last 0 lines/bytes'), matching GNU head.
    """
    try:
        value = int(text, 10)
    except ValueError:
        raise SystemExit(f"headlite: invalid count: {text!r}")
    return text.lstrip().startswith("-"), abs(value)

